function BalancerForgePure(){
  // ==================== FNV-1a 32 位哈希（确定性，跨平台一致）====================
  function utf8Bytes(s){
    var out = [], i, c;
    for (i = 0; i < s.length; i++){
      c = s.charCodeAt(i);
      if (c < 0x80) out.push(c);
      else if (c < 0x800){ out.push(0xC0 | (c >> 6), 0x80 | (c & 63)); }
      else if (c >= 0xD800 && c <= 0xDBFF && i + 1 < s.length){
        var c2 = s.charCodeAt(i + 1);
        var cp = 0x10000 + ((c - 0xD800) << 10) + (c2 - 0xDC00); i++;
        out.push(0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
      } else { out.push(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); }
    }
    return out;
  }
  function fnv1a(str){
    var b = utf8Bytes(String(str)), h = 0x811c9dc5;
    for (var i = 0; i < b.length; i++){
      h ^= b[i];
      h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
    }
    return h >>> 0;
  }

  // FNV-1a 对 "a#0" / "a#1" 这类只差末字符的短串雪崩不足，
  // 直接拿它当虚拟节点坐标会让同一节点的点扎堆，环占比严重失衡（实测 4 节点 ×200 vnode 会偏到 16% : 33%）。
  // 这里在 FNV 之后再套一层 murmur3 终混，只用于哈希环，fnv1a 本身保持标准实现不变。
  function mix32(h){
    h = (h ^ (h >>> 16)) >>> 0;
    h = Math.imul(h, 0x85ebca6b) >>> 0;
    h = (h ^ (h >>> 13)) >>> 0;
    h = Math.imul(h, 0xc2b2ae35) >>> 0;
    h = (h ^ (h >>> 16)) >>> 0;
    return h;
  }
  function ringHash(str){ return mix32(fnv1a(str)); }

  // ==================== 后端解析 ====================
  function parseBackends(text){
    var s = String(text == null ? '' : text).trim();
    if (s === '') return {error:'请至少输入一个后端节点'};
    var lines = s.replace(/\r\n/g, '\n').split(/[\n,]/), out = [], seen = {};
    for (var i = 0; i < lines.length; i++){
      var ln = lines[i];
      var hash = ln.indexOf('#'); if (hash >= 0) ln = ln.slice(0, hash);
      ln = ln.trim();
      if (ln === '') continue;
      var name, w = 1;
      var m = /^(\S+)\s*[=\s]\s*(\d+(?:\.\d+)?)$/.exec(ln);
      if (m){ name = m[1]; w = Number(m[2]); }
      else if (/\s/.test(ln)) return {error:'无法解析节点行：' + ln + '（应为 name 或 name=weight）'};
      else name = ln;
      if (seen[name]) return {error:'重复的节点名：' + name};
      if (!(w > 0)) return {error:'节点 ' + name + ' 的权重必须大于 0'};
      seen[name] = 1;
      out.push({name:name, weight:w});
    }
    if (!out.length) return {error:'请至少输入一个后端节点'};
    if (out.length > 500) return {error:'节点数量过多（上限 500）'};
    return {error:null, backends:out};
  }

  // ==================== 分布统计 ====================
  function stats(counts, backends){
    var names = [], vals = [], total = 0, i;
    for (i = 0; i < backends.length; i++){
      names.push(backends[i].name);
      var v = counts[backends[i].name] || 0;
      vals.push(v); total += v;
    }
    var mean = vals.length ? total / vals.length : 0;
    var max = -Infinity, min = Infinity, sq = 0;
    for (i = 0; i < vals.length; i++){
      if (vals[i] > max) max = vals[i];
      if (vals[i] < min) min = vals[i];
      sq += (vals[i] - mean) * (vals[i] - mean);
    }
    if (!vals.length){ max = 0; min = 0; }
    var sd = vals.length ? Math.sqrt(sq / vals.length) : 0;
    // 相对期望份额的最大偏差（按权重归一）
    var wTotal = 0;
    for (i = 0; i < backends.length; i++) wTotal += backends[i].weight;
    var maxDev = 0;
    for (i = 0; i < backends.length; i++){
      var expect = total * backends[i].weight / wTotal;
      if (expect > 0) maxDev = Math.max(maxDev, Math.abs(vals[i] - expect) * 100 / expect);
    }
    return {
      names:names, values:vals, total:total, mean:mean, max:max, min:min,
      stddev:sd, cv:(mean ? sd / mean : 0),
      imbalancePct:(mean ? (max - mean) * 100 / mean : 0),
      maxWeightDevPct:maxDev
    };
  }

  // ==================== 1. 轮询 ====================
  function roundRobin(backends, n){
    var seq = [], counts = {};
    for (var i = 0; i < n; i++){
      var b = backends[i % backends.length].name;
      seq.push(b); counts[b] = (counts[b] || 0) + 1;
    }
    return {seq:seq, counts:counts};
  }

  // ==================== 2. 平滑加权轮询（nginx SWRR）====================
  function smoothWeightedRR(backends, n){
    var cur = [], total = 0, i;
    for (i = 0; i < backends.length; i++){ cur.push(0); total += backends[i].weight; }
    var seq = [], counts = {};
    for (var k = 0; k < n; k++){
      var best = -1, bestVal = -Infinity;
      for (i = 0; i < backends.length; i++){
        cur[i] += backends[i].weight;
        if (cur[i] > bestVal){ bestVal = cur[i]; best = i; }
      }
      cur[best] -= total;
      var nm = backends[best].name;
      seq.push(nm); counts[nm] = (counts[nm] || 0) + 1;
    }
    return {seq:seq, counts:counts};
  }

  // ==================== 3. 最少连接（含权重）====================
  function leastConn(backends, n, serviceTicks){
    var st = serviceTicks || 3;
    var ends = [], cw = [], i;
    for (i = 0; i < backends.length; i++){ ends.push([]); cw.push(0); }
    var seq = [], counts = {}, peak = 0;
    for (var t = 0; t < n; t++){
      for (i = 0; i < backends.length; i++){
        ends[i] = ends[i].filter(function(e){ return e > t; });
      }
      // 先按「连接数 / 权重」取最小负载，再在并列者之间用平滑加权轮询决胜
      // （nginx least_conn 的做法：否则连接数相同时会永远命中第一个节点，末位节点被饿死）
      var bestLoad = Infinity, load;
      for (i = 0; i < backends.length; i++){
        load = ends[i].length / backends[i].weight;
        if (load < bestLoad - 1e-9) bestLoad = load;
      }
      var tied = [], sumW = 0;
      for (i = 0; i < backends.length; i++){
        load = ends[i].length / backends[i].weight;
        if (load < bestLoad + 1e-9){ tied.push(i); sumW += backends[i].weight; }
      }
      var best = tied[0];
      if (tied.length > 1){
        var bestCw = -Infinity;
        for (var k = 0; k < tied.length; k++){
          var idx = tied[k];
          cw[idx] += backends[idx].weight;
          if (cw[idx] > bestCw){ bestCw = cw[idx]; best = idx; }
        }
        cw[best] -= sumW;
      }
      ends[best].push(t + st);
      var live = 0;
      for (i = 0; i < backends.length; i++) live += ends[i].length;
      if (live > peak) peak = live;
      var nm = backends[best].name;
      seq.push(nm); counts[nm] = (counts[nm] || 0) + 1;
    }
    return {seq:seq, counts:counts, peakConcurrency:peak};
  }

  // ==================== 4. 两次随机选优（P2C，确定性 LCG）====================
  function p2c(backends, n, seed, serviceTicks){
    var st = serviceTicks || 3, s = (seed === undefined ? 12345 : seed) >>> 0;
    function rnd(){ s = (Math.imul(s, 1103515245) + 12345) >>> 0; return s % 2147483648; }
    var ends = [], i;
    for (i = 0; i < backends.length; i++) ends.push([]);
    var seq = [], counts = {};
    for (var t = 0; t < n; t++){
      for (i = 0; i < backends.length; i++) ends[i] = ends[i].filter(function(e){ return e > t; });
      var a = rnd() % backends.length, b = rnd() % backends.length;
      if (backends.length > 1){ var guard = 0; while (b === a && guard++ < 8) b = rnd() % backends.length; }
      var la = ends[a].length / backends[a].weight, lb = ends[b].length / backends[b].weight;
      var pick = (la <= lb) ? a : b;
      ends[pick].push(t + st);
      var nm = backends[pick].name;
      seq.push(nm); counts[nm] = (counts[nm] || 0) + 1;
    }
    return {seq:seq, counts:counts};
  }

  // ==================== 5. 一致性哈希环 ====================
  function buildRing(backends, vnodes){
    var v = vnodes || 160, pts = [];
    for (var i = 0; i < backends.length; i++){
      for (var j = 0; j < v; j++){
        pts.push({h:ringHash(backends[i].name + '#' + j), node:backends[i].name});
      }
    }
    pts.sort(function(a, b){ return a.h - b.h || (a.node < b.node ? -1 : a.node > b.node ? 1 : 0); });
    return {points:pts, vnodes:v};
  }
  function ringLookup(ring, key){
    var pts = ring.points;
    if (!pts.length) return null;
    var h = ringHash(key), lo = 0, hi = pts.length - 1, ans = -1;
    while (lo <= hi){
      var mid = (lo + hi) >> 1;
      if (pts[mid].h >= h){ ans = mid; hi = mid - 1; } else lo = mid + 1;
    }
    if (ans < 0) ans = 0;   // 环形回绕
    return pts[ans].node;
  }
  function ringShare(ring){
    var pts = ring.points, share = {}, i;
    if (!pts.length) return share;
    var TOTAL = 4294967296;
    for (i = 0; i < pts.length; i++){
      var prev = (i === 0) ? pts[pts.length - 1].h - TOTAL : pts[i - 1].h;
      var span = pts[i].h - prev;
      share[pts[i].node] = (share[pts[i].node] || 0) + span;
    }
    for (var k in share) if (Object.prototype.hasOwnProperty.call(share, k)) share[k] = share[k] * 100 / TOTAL;
    return share;
  }
  function consistentHash(backends, keys, vnodes){
    var ring = buildRing(backends, vnodes), counts = {}, map = {};
    for (var i = 0; i < keys.length; i++){
      var node = ringLookup(ring, keys[i]);
      map[keys[i]] = node;
      counts[node] = (counts[node] || 0) + 1;
    }
    return {counts:counts, map:map, ring:ring, share:ringShare(ring)};
  }
  function moduloHash(backends, keys){
    var counts = {}, map = {};
    for (var i = 0; i < keys.length; i++){
      var node = backends[fnv1a(keys[i]) % backends.length].name;
      map[keys[i]] = node;
      counts[node] = (counts[node] || 0) + 1;
    }
    return {counts:counts, map:map};
  }

  function migration(before, after){
    var moved = 0, total = 0, k;
    for (k in before){
      if (!Object.prototype.hasOwnProperty.call(before, k)) continue;
      total++;
      if (after[k] !== before[k]) moved++;
    }
    return {moved:moved, total:total, pct:(total ? moved * 100 / total : 0)};
  }

  function genKeys(n, prefix){
    var out = [], p = prefix === undefined ? 'key' : prefix;
    for (var i = 0; i < n; i++) out.push(p + i);
    return out;
  }

  // 摘除一个节点后的迁移率对比：一致性哈希 vs 取模
  function ejectionReport(backends, keyCount, vnodes, ejectName){
    if (backends.length < 2) return {error:'至少需要 2 个节点才能演示摘除'};
    var keys = genKeys(keyCount);
    var victim = ejectName || backends[backends.length - 1].name;
    var rest = backends.filter(function(b){ return b.name !== victim; });
    if (rest.length === backends.length) return {error:'找不到要摘除的节点：' + victim};

    var chBefore = consistentHash(backends, keys, vnodes);
    var chAfter = consistentHash(rest, keys, vnodes);
    var moBefore = moduloHash(backends, keys);
    var moAfter = moduloHash(rest, keys);

    // 一致性哈希的关键性质：不属于被摘除节点的 key 不应发生迁移
    var collateral = 0;
    for (var k in chBefore.map){
      if (!Object.prototype.hasOwnProperty.call(chBefore.map, k)) continue;
      if (chBefore.map[k] !== victim && chAfter.map[k] !== chBefore.map[k]) collateral++;
    }
    return {
      error:null, victim:victim, keys:keys.length, vnodes:(vnodes || 160),
      consistent:migration(chBefore.map, chAfter.map),
      modulo:migration(moBefore.map, moAfter.map),
      collateralMoves:collateral,
      shareBefore:chBefore.share, shareAfter:chAfter.share
    };
  }

  // ==================== 权重表达力体检 ====================
  // 最少连接只有在「在途并发 ≥ 权重之和」时才表达得出权重差异：
  // 并发太低时，权重 5 的节点还没攒够 5 条连接，负载（连接数/权重）就已经比对手高，
  // 分流会退化成接近等分，看起来像是权重没生效。
  function weightExpression(backends, peakConcurrency){
    var wTotal = 0, wMax = 1, i;
    for (i = 0; i < backends.length; i++){
      wTotal += backends[i].weight;
      if (backends[i].weight > wMax) wMax = backends[i].weight;
    }
    var peak = Number(peakConcurrency) || 0;
    var sufficient = peak >= wTotal;
    return {
      weightTotal:wTotal, maxWeight:wMax, peakConcurrency:peak,
      needConcurrency:wTotal, sufficient:sufficient,
      note:sufficient
        ? '在途并发 ' + peak + ' ≥ 权重之和 ' + wTotal + '，最少连接能如实表达权重比例'
        : '在途并发 ' + peak + ' 低于权重之和 ' + wTotal + '，最少连接表达不出权重差异，分流会退化成接近等分；想按权重分流请改用平滑加权轮询'
    };
  }

  // ==================== 汇总对比 ====================
  var ALGOS = ['roundRobin','swrr','leastConn','p2c','consistentHash'];
  function compare(backends, n, opts){
    var o = opts || {};
    var keys = genKeys(n);
    var res = {};
    res.roundRobin = roundRobin(backends, n);
    res.swrr = smoothWeightedRR(backends, n);
    res.leastConn = leastConn(backends, n, o.serviceTicks);
    res.p2c = p2c(backends, n, o.seed, o.serviceTicks);
    res.consistentHash = consistentHash(backends, keys, o.vnodes);
    var out = [];
    for (var i = 0; i < ALGOS.length; i++){
      var a = ALGOS[i];
      out.push({algo:a, counts:res[a].counts, stats:stats(res[a].counts, backends)});
    }
    return {rows:out, raw:res};
  }

  function analyze(text, n, opts){
    var pb = parseBackends(text);
    if (pb.error) return {error:pb.error};
    var reqs = Number(n) || 0;
    if (reqs < 1 || reqs > 200000) return {error:'请求数需在 1..200000'};
    var o = opts || {};
    var cmp = compare(pb.backends, reqs, o);
    var ej = ejectionReport(pb.backends, Math.min(reqs, 20000), o.vnodes, o.eject);
    var wTotal = 0;
    for (var i = 0; i < pb.backends.length; i++) wTotal += pb.backends[i].weight;
    return {
      error:null, backends:pb.backends, requests:reqs, weightTotal:wTotal,
      rows:cmp.rows, swrrSeq:cmp.raw.swrr.seq.slice(0, 32),
      peakConcurrency:cmp.raw.leastConn.peakConcurrency,
      weightExpression:weightExpression(pb.backends, cmp.raw.leastConn.peakConcurrency),
      ejection:ej
    };
  }

  var api = {fnv1a:fnv1a, mix32:mix32, ringHash:ringHash, parseBackends:parseBackends, stats:stats, roundRobin:roundRobin,
             smoothWeightedRR:smoothWeightedRR, leastConn:leastConn, p2c:p2c,
             buildRing:buildRing, ringLookup:ringLookup, ringShare:ringShare,
             consistentHash:consistentHash, moduloHash:moduloHash, migration:migration,
             genKeys:genKeys, ejectionReport:ejectionReport, weightExpression:weightExpression,
             compare:compare, analyze:analyze,
             ALGOS:ALGOS};
  if (typeof window !== 'undefined'){ window.__PURE__ = api; }
  if (typeof module !== 'undefined' && module.exports){ module.exports = {BalancerForgePure:BalancerForgePure}; }
  return api;
}
